if not doc.fee_structure:
    if frappe.db.exists("Fee Structure",{'class':doc.program,'academic_year':doc.academic_year}):
        doc.fee_structure = frappe.db.get_value("Fee Structure",{'class':doc.program,'academic_year':doc.academic_year})

if doc.fee_structure:
    fsh = frappe.db.get_value("Fee Schedule",{'fee_structure':doc.fee_structure},'name')
    doc.fee_schedule = fsh
    doc.application_fees = frappe.db.get_value("Application Fees List",{'class_name':doc.program},'application_fees')

deposit = []
for component in doc.components:
    fee_name = component.fees_category
    if frappe.db.exists("Security Deposit", fee_name):
        sd = frappe.get_doc("Security Deposit", fee_name)
        if fee_name not in deposit and doc.academic_year == sd.academic_year:
            deposit.append(fee_name)
        else:
            frappe.throw(f"Duplicate Deposite: {fee_name}")

doc.total_amount = 0
for d in doc.components:
	doc.total_amount = doc.total_amount +  d.amount

doc.total_amount = 0
for d in doc.components:
	doc.total_amount = doc.total_amount +  d.amount

charge = 0
if frappe.db.exists("Payment Methods",{'method':frappe.form_dict.pm}):
    charge = frappe.db.get_value("Payment Methods",{'method':frappe.form_dict.pm},'charge')
payment_request = frappe.db.get_value("Payment Request",{'payment_hash':frappe.form_dict.pr},'name')
payment_request = frappe.get_doc("Payment Request",payment_request)
frappe.response['message'] = {'charge':charge,'url':payment_request.get_payment_url(payment_method=frappe.form_dict.pm)}

if frappe.db.exists("Fee Category", {"name": doc.fee_category}):
    company = frappe.db.get_value("Fee Category", {"name": doc.fee_category}, "custom_company")
    doc.company = company

fee = frappe.get_doc("Fees", doc.reference_name)
if fee.payment_plan is not None:
    for ps in fee.payment_schedule:
        d = ps.due_date
        today = frappe.utils.getdate(frappe.utils.today())
        if frappe.utils.date_diff(d, today) < 30:
            doc.payment_term = ps.payment_term

pe = frappe.get_doc("Program Enrollment", doc.program_enrollment)
if pe.custom_payment_plan is not None:
    doc.payment_plan = pe.custom_payment_plan

if frappe.db.exists("Payment Request", {"reference_name":doc.reference_name, "docstatus": 1}):
    pr = frappe.get_doc("Payment Request", {"reference_name":doc.reference_name, "docstatus": 1})
    if not pr.docstatus.is_cancelled():
        pr.cancel()

    fees = frappe.get_doc("Fees", doc.reference_name)
    amount = 0
    for schedule in fees.payment_schedule:
        if schedule.due_date < frappe.utils.getdate(frappe.utils.today()):
            amount = amount + frappe.utils.flt(schedule.payment_amount)
            frappe.db.set_value("Payment Schedule", schedule.name, "payment_amount", 0)
        if schedule.payment_term == doc.payment_term:
            amount = amount + frappe.utils.flt(schedule.payment_amount)
            frappe.db.set_value("Payment Schedule", schedule.name, "payment_amount", amount)

    doc.amount = amount

student_groups = []

for sg in doc.student_groups:
    student_groups.append(sg.student_group_name)
for sg in doc.student_groups:
    if student_groups.count(sg.student_group_name)>1:
      frappe.throw(_("Student Group cannot be added multiple times"))

filters = {"academic_year": doc.academic_year, "program": doc.program, "student_category": doc.student_category}
if frappe.db.exists("Student Group", filters):
    sg = frappe.get_doc("Student Group", filters)
    roll_no = len(sg.students)+1
    sg.append("students", {
        "student":doc.student,
        "student_name": doc.student_name,
        "group_roll_number": roll_no,
        "active": 1
    })
    sg.save()

    if frappe.db.exists("Fee Schedule", filters):
        fs = frappe.get_doc("Fee Schedule", filters)
        for g in fs.student_groups:
            if g.student_group == sg.name:
                total_students = int(g.total_students) + 1
                frappe.db.set_value("Fee Schedule Student Group", g.name, "total_students", total_students)

student = frappe.get_doc("Student",doc.student)
student.append("class_details",{
    'program_enrollment': doc.name,
    'payment_plan': doc.payment_plan
})
student.save()

for i in doc.payment_schedule:
    if i.due_date:
        doc.due_date = i.due_date
        break

if not doc.payment_plan:
    pe = frappe.get_doc("Program Enrollment", doc.program_enrollment)
    if pe.custom_payment_plan is not None:
        doc.payment_plan = pe.custom_payment_plan
    else:
        doc.payment_plan = frappe.db.get_value("Fee Schedule",doc.fee_schedule,'payment_plan')
if doc.payment_plan:
            pp = frappe.get_doc("Payment Plan",doc.payment_plan)
            doc.payment_schedule = []
            initial_payment = 0
            for component in doc.components:
                if component.fees_category in ["Deposit","deposit", "Application Fee","Application fee"]:
                    initial_payment = initial_payment +  component.amount
            i=0
            for schedule in pp.payment_schedule:
                payment_amount = schedule.payment_amount
                description = "Installment - " + str(i+1)
                if i==0 and initial_payment>0:
                    payment_amount = payment_amount + initial_payment
                    description = description + " and deposit/application fee"
                i= i+1
                doc.append("payment_schedule",{
                    'payment_term': schedule.payment_term,
                    'description': description,
                    'due_date': schedule.due_date,
                    'invoice_portion': schedule.invoice_portion,
                    'payment_amount': payment_amount,
                    'outstanding': payment_amount,
                })
